  "source": "def investigate(context, acquire):
    events = context.get('events', [])
    state = 'open'
    pending = []
    count = 0

    def continuation(byte):
        return 128 <= byte <= 191

    def decode_chunk(data, final):
        nonlocal pending, count, state
        if state != 'open':
            return
        buffer = pending + list(data)
        pending = []
        index = 0
        length = len(buffer)
        while index < length:
            byte = buffer[index]
            if byte < 128:
                count += 1
                index += 1
            elif byte < 192:
                state = 'error'
                return
            elif byte < 224:
                needed = 1
                low = 128
                high = 191
            elif byte < 240:
                needed = 2
                if byte == 224:
                    low = 160
                else:
                    low = 128
                high = 191
            elif byte < 248:
                needed = 3
                if byte == 240:
                    low = 160
                    high = 191
                elif byte == 244:
                    low = 128
                    high = 143
                else:
                    low = 128
                    high = 191
            else:
                state = 'error'
                return
            if index + needed + 1 > length:
                if final:
                    state = 'error'
                    return
                pending = buffer[index:]
                return
            valid = True
            for offset in range(1, needed + 1):
                next_byte = buffer[index + offset]
                if offset == 1 and (next_byte < low or next_byte > high):
                    valid = False
                    break
                if offset > 1 and not continuation(next_byte):
                    valid = False
                    break
            if not valid:
                state = 'error'
                return
            count += 1
            index += needed + 1
        if final:
            state = 'finished'

    for event in events:
        op = event.get('op')
        if op == 'feed':
            decode_chunk(event.get('bytes', []), False)
        elif op == 'finish':
            decode_chunk([], True)
        elif op == 'reset':
            state = 'open'
            pending = []
            count = 0
    return {'count': count, 'status': state}
